// itinerary order, media assets and package identifiers.
const exclusions = [
  "Vuelos internacionales y nacionales",
  "Almuerzos y cenas",
  "Seguro de viaje personal, visados, propinas y gastos personales",
  "Mejoras de categoría y habitaciones individuales adicionales",
  "Suplementos por festivos, servicios nocturnos, horas adicionales o servicios ajenos al itinerario reservado",
] as const;
const booking = "Los precios de partida por persona corresponden a grupos de 2, 4 y 6 viajeros, sin vuelos. Para otro número de viajeros preparamos un presupuesto personalizado. Indica las fechas, las habitaciones que necesitas, los horarios de llegada y el número de maletas: comprobaremos la disponibilidad y te enviaremos el presupuesto definitivo antes del pago.";
const standardPackage = [{ id: "standard-guided", label: "Viaje privado", summary: "Vehículo privado, visitas con guía en inglés, traslados de llegada y salida, entradas para adultos indicadas en el programa y alojamiento con desayuno. Sin paradas obligatorias en tiendas." }] as const;
const days = (rows: readonly (readonly [string, string])[]) => rows.map(([title, description]) => ({ title, description }));
const media = (rows: readonly (readonly [number, string, string, string])[]) => {
  const result: { day: number; variants: { label: string; alt: string; caption: string }[] }[] = [];
  for (const [day, label, alt, caption] of rows) {
    let item = result.find(entry => entry.day === day);
    if (!item) { item = { day, variants: [] }; result.push(item); }
    item.variants.push({ label, alt, caption });
  }
  return result;
};
const qa = (rows: readonly (readonly [string, string])[]) => rows.map(([question, answer]) => ({ question, answer }));

